package pbl6.ctsv.mghp.configuration;
import java.sql.*;import java.time.*;import java.util.*;import com.fasterxml.jackson.databind.*;import org.springframework.jdbc.core.JdbcTemplate;
/** Typed columns only. Mapping lists are static SQL identifiers, never supplied by requests. */
final class ConfigurationRepository {
 final JdbcTemplate jdbc;final ObjectMapper json;final jakarta.persistence.EntityManager em;
 static final String[][] POLICY={
  {"name","ten_tai_thoi_diem_chot"},{"rate","ty_le_giam"},{"scopeCode","ma_pham_vi"},{"effectiveFrom","ngay_bat_dau_hieu_luc"},{"effectiveUntil","ngay_ket_thuc_hieu_luc"},{"legalBasis","can_cu_phap_ly"},{"ruleVersion","phien_ban_quy_tac_xet"},{"benefitDuration","thoi_han_huong"},{"tiePriority","uu_tien_khi_cung_muc"},{"documentNumber","so_van_ban_ap_dung"},{"article","dieu_khoan_ap_dung"},{"sourceUrl","url_can_cu"},{"evidenceUpdateMode","che_do_cap_nhat_minh_chung"},{"evidenceUpdateGuidance","huong_dan_cap_nhat_minh_chung"},{"minimumAge","tuoi_toi_thieu"},{"maximumAge","tuoi_toi_da"},{"ageReferenceRule","quy_tac_moc_tuoi"},{"firstDegreeRequired","yeu_cau_van_bang_thu_nhat"}};
 static final String[][] CRITERION={{"code","ma"},{"name","ten"},{"assessmentGuidance","huong_dan_xet"},{"required","bat_buoc"},{"conditional","co_dieu_kien_ap_dung"},{"applicabilityGuidance","huong_dan_ap_dung"},{"order","thu_tu_hien_thi"}};
 static final String[][] GROUP={{"code","ma"},{"name","ten"},{"minimumRequired","so_yeu_cau_toi_thieu_dat"},{"order","thu_tu_hien_thi"}};
 static final String[][] DOCUMENT={{"code","ma"},{"name","ten"},{"type","loai_giay_to"},{"hardCopyRequired","can_doi_chieu_ban_giay"},{"maxAgeDays","tuoi_toi_da_giay_to_theo_ngay"},{"order","thu_tu_hien_thi"},{"certifiedCopyRequired","can_ban_sao_chung_thuc"},{"stampRequired","can_dau_xac_nhan"},{"confirmationContent","noi_dung_xac_nhan"},{"confirmingAuthority","co_quan_xac_nhan"},{"reviewGuidance","huong_dan_kiem_tra"},{"evidenceSubject","chu_the_minh_chung"}};
 static final String[][] ROUND={{"code","ma_dot_xet"},{"semesterId","hoc_ky_id"},{"name","ten"},{"description","mo_ta"},{"opensAt","thoi_diem_mo"},{"submissionDeadline","han_nop"},{"reviewDeadline","han_ra_soat"},{"declarationGuidance","huong_dan_ke_khai"},{"lateSubmissionGuidance","huong_dan_can_cu_nop_muon"},{"allowRetroactive","cho_phep_truy_linh"},{"retroactiveMode","che_do_truy_linh"},{"midSemesterMode","cach_xet_thay_doi_giua_ky"}};
 ConfigurationRepository(JdbcTemplate jdbc,ObjectMapper json,jakarta.persistence.EntityManager em){this.jdbc=jdbc;this.json=json;this.em=em;}
 List<Map<String,Object>> rows(String sql,Object...args){return jdbc.query(sql,(r,n)->{var m=new LinkedHashMap<String,Object>();for(int i=1;i<=r.getMetaData().getColumnCount();i++){Object v=r.getObject(i);if(v instanceof Long)v=v.toString();if(v instanceof java.math.BigDecimal d)v=d.toPlainString();if(v instanceof java.sql.Date d)v=d.toLocalDate().toString();if(v instanceof OffsetDateTime d)v=d.toInstant().toString();if(v!=null&&v.getClass().getName().equals("microsoft.sql.DateTimeOffset"))v=r.getObject(i,OffsetDateTime.class).toInstant().toString();m.put(r.getMetaData().getColumnLabel(i),v);}return m;},args);}
 Map<String,Object> one(String sql,Object...args){var rows=rows(sql,args);if(rows.size()!=1)throw new ConfigFailure(404,"NOT_FOUND");return rows.getFirst();}
 static String select(String[][] fields){return String.join(",",Arrays.stream(fields).map(f->"["+f[1]+"] ["+f[0]+"]").toList());}
 static LinkedHashMap<String,Object> values(JsonNode n,String[][] fields){var m=new LinkedHashMap<String,Object>();for(var f:fields){var v=n.path(f[0]);Object value=v.isNull()?null:v.isBoolean()?v.booleanValue():v.isIntegralNumber()?v.intValue():v.asText();if(!v.isNull()){if(f[0].equals("rate"))value=new java.math.BigDecimal(v.asText());if(f[0].endsWith("Id"))value=ConfigRules.id(v.asText());if(f[0].startsWith("effective"))value=java.sql.Date.valueOf(v.asText());if(Set.of("opensAt","submissionDeadline","reviewDeadline").contains(f[0]))value=OffsetDateTime.parse(v.asText()).withOffsetSameInstant(ZoneOffset.UTC);}m.put(f[1],value);}return m;}
 long insert(String table,LinkedHashMap<String,Object> values){
  if(table.startsWith("mghp_")){
   Object entity=ConfigurationEntities.create(table,values);em.persist(entity);em.flush();
   return ((Number)em.getEntityManagerFactory().getPersistenceUnitUtil().getIdentifier(entity)).longValue();
  }
  if(!table.equals("thong_bao"))throw new IllegalArgumentException("Unsupported insert table");
  String cols=String.join(",",values.keySet().stream().map(k->"["+k+"]").toList()),marks=String.join(",",Collections.nCopies(values.size(),"?"));
  return jdbc.queryForObject("DECLARE @ids TABLE(id bigint); INSERT dbo."+table+"("+cols+") OUTPUT INSERTED.id INTO @ids VALUES("+marks+"); SELECT id FROM @ids",Long.class,values.values().toArray());
 }
 void cas(String table,long id,byte[] fence,LinkedHashMap<String,Object> v){em.flush();String c=String.join(",",v.keySet().stream().map(k->"["+k+"]=?").toList());var a=new ArrayList<Object>(v.values());a.add(id);a.add(fence);if(jdbc.update("UPDATE dbo."+table+" SET "+c+" WHERE id=? AND "+column(table)+"=?",a.toArray())!=1)throw new ConfigFailure(412,"VERSION_CONFLICT");em.clear();}
 byte[] fence(String table,long id){em.flush();var r=jdbc.query("SELECT "+column(table)+" FROM dbo."+table+" WITH(UPDLOCK,HOLDLOCK) WHERE id=?",(s,n)->s.getBytes(1),id);if(r.size()!=1)throw new ConfigFailure(404,"NOT_FOUND");return r.getFirst();}
 static String column(String table){return table.equals("mghp_phien_ban_chinh_sach")?"phien_ban_ky_thuat":"phien_ban";}
 void serializeWrites(){jdbc.queryForObject("DECLARE @r int; EXEC @r=sys.sp_getapplock @Resource=N'ctsv.mghp.configuration',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=5000; SELECT @r",(r,n)->{if(r.getInt(1)<0)throw new ConfigFailure(503,"DEPENDENCY_UNAVAILABLE");return r.getInt(1);});}
 void audit(long user,String action,String type,long id,String reason){jdbc.update("INSERT dbo.nhat_ky_thao_tac(su_kien_id,loai_chu_the_thao_tac,nguoi_dung_id,hanh_dong,loai_doi_tuong,doi_tuong_id,ly_do,thoi_diem_tao) VALUES(?,N'user',?,?,?,?,?,SYSUTCDATETIME())",UUID.randomUUID().toString(),user,action,type,""+id,reason);}
 long policy(long id){var r=jdbc.query("SELECT id FROM dbo.mghp_chinh_sach WITH(UPDLOCK,HOLDLOCK) WHERE id=?",(s,n)->s.getLong(1),id);if(r.isEmpty())throw new ConfigFailure(404,"NOT_FOUND");return r.getFirst();}
 String policyCode(long version){return find(pbl6.ctsv.mghp.configuration.entity.MghpPhienBanChinhSach.class,version).getChinhSach().getMa();}
 <T>T find(Class<T> type,long id){T value=em.find(type,id);if(value==null)throw new ConfigFailure(404,"NOT_FOUND");return value;}
 List<Map<String,Object>> policies(){return em.createQuery("from MghpChinhSach order by ma,id",pbl6.ctsv.mghp.configuration.entity.MghpChinhSach.class).getResultList().stream().map(p->{var m=new LinkedHashMap<String,Object>();m.put("id",p.getId().toString());m.put("code",p.getMa());m.put("name",p.getTen());m.put("group",p.getNhomChinhSach());m.put("active",p.getDangHoatDong());return (Map<String,Object>)m;}).toList();}
 int nextVersion(long policy){return jdbc.queryForObject("SELECT COALESCE(MAX(phien_ban),0)+1 FROM dbo.mghp_phien_ban_chinh_sach WITH(UPDLOCK,HOLDLOCK) WHERE chinh_sach_id=?",Integer.class,policy);}
 List<Map<String,Object>> versions(long policy){
  policy(policy);return em.createQuery("from MghpPhienBanChinhSach where chinhSachId=:id order by phienBan desc,id desc",pbl6.ctsv.mghp.configuration.entity.MghpPhienBanChinhSach.class).setParameter("id",policy).getResultList().stream().map(p->{
   var all=ConfigurationMapper.policy(p);var m=new LinkedHashMap<String,Object>();for(String key:List.of("id","policyId","version","name","rate","scopeCode","effectiveFrom","effectiveUntil","status","ruleVerificationStatus"))m.put(key,all.get(key));return (Map<String,Object>)m;}).toList();
 }
 Map<String,Object> policyView(long id){
  var m=ConfigurationMapper.policy(find(pbl6.ctsv.mghp.configuration.entity.MghpPhienBanChinhSach.class,id));
  m.put("criteria",em.createQuery("from MghpTieuChiChinhSach where phienBanChinhSachId=:id order by case when thuTuHienThi is null then 1 else 0 end,thuTuHienThi,id",pbl6.ctsv.mghp.configuration.entity.MghpTieuChiChinhSach.class).setParameter("id",id).getResultList().stream().map(ConfigurationMapper::criterion).toList());
  var groups=em.createQuery("from MghpNhomYeuCauGiayTo where phienBanChinhSachId=:id order by case when thuTuHienThi is null then 1 else 0 end,thuTuHienThi,id",pbl6.ctsv.mghp.configuration.entity.MghpNhomYeuCauGiayTo.class).setParameter("id",id).getResultList().stream().map(g->{
   var group=ConfigurationMapper.group(g);group.put("documents",em.createQuery("from MghpGiayToBatBuoc where nhomId=:id order by case when thuTuHienThi is null then 1 else 0 end,thuTuHienThi,id",pbl6.ctsv.mghp.configuration.entity.MghpGiayToBatBuoc.class).setParameter("id",g.getId()).getResultList().stream().map(ConfigurationMapper::document).toList());return group;}).toList();m.put("documentGroups",groups);return m;
 }
 void children(long version,JsonNode n,boolean replace){em.flush();if(replace){jdbc.update("DELETE d FROM dbo.mghp_giay_to_bat_buoc d JOIN dbo.mghp_nhom_yeu_cau_giay_to g ON g.id=d.nhom_id WHERE g.phien_ban_chinh_sach_id=?",version);jdbc.update("DELETE dbo.mghp_nhom_yeu_cau_giay_to WHERE phien_ban_chinh_sach_id=?",version);jdbc.update("DELETE dbo.mghp_tieu_chi_chinh_sach WHERE phien_ban_chinh_sach_id=?",version);}
  for(var c:n.path("criteria")){var v=values(c,CRITERION);v.put("phien_ban_chinh_sach_id",version);insert("mghp_tieu_chi_chinh_sach",v);}for(var g:n.path("documentGroups")){var v=values(g,GROUP);v.put("phien_ban_chinh_sach_id",version);long group=insert("mghp_nhom_yeu_cau_giay_to",v);for(var d:g.path("documents")){var dv=values(d,DOCUMENT);dv.put("nhom_id",group);insert("mghp_giay_to_bat_buoc",dv);}}
  em.flush();em.clear();
 }
 boolean usedPolicy(long id){return jdbc.queryForObject("SELECT (SELECT COUNT(*) FROM dbo.mghp_ho_so WHERE phien_ban_chinh_sach_id=?)+(SELECT COUNT(*) FROM dbo.mghp_danh_gia_dieu_kien WHERE phien_ban_chinh_sach_id=?)+(SELECT COUNT(*) FROM dbo.mghp_chinh_sach_dot_xet b JOIN dbo.mghp_dot_xet r ON r.id=b.dot_xet_id WHERE b.phien_ban_chinh_sach_id=? AND r.thoi_diem_khoa_cau_hinh IS NOT NULL)",Integer.class,id,id,id)>0;}
 Map<String,Object> roundView(long id,boolean manager){
  var r=find(pbl6.ctsv.mghp.configuration.entity.MghpDotXet.class,id);if(!manager&&!Set.of("open","closed","completed").contains(r.getTrangThai()==null?"":r.getTrangThai()))throw new ConfigFailure(404,"NOT_FOUND");
  var m=ConfigurationMapper.round(r,manager);m.put("policyVersions",em.createQuery("from MghpChinhSachDotXet where dotXetId=:id order by case when thuTuHienThi is null then 1 else 0 end,thuTuHienThi,id",pbl6.ctsv.mghp.configuration.entity.MghpChinhSachDotXet.class).setParameter("id",id).getResultList().stream().map(p->{var v=new LinkedHashMap<String,Object>();v.put("policyVersionId",p.getPhienBanChinhSachId().toString());v.put("applicationTemplateFileId",p.getTepMauDonId()==null?null:p.getTepMauDonId().toString());v.put("order",p.getThuTuHienThi());return v;}).toList());return m;
 }
 Object rounds(boolean manager,Long semester,int[] page){
  String where=" where (:semester is null or r.hocKyId=:semester)"+(manager?"":" and r.trangThai in ('open','closed','completed')");
  var items=em.createQuery("select r from MghpDotXet r"+where+" order by case when r.thoiDiemMo is null then 1 else 0 end,r.thoiDiemMo desc,r.id desc",pbl6.ctsv.mghp.configuration.entity.MghpDotXet.class).setParameter("semester",semester).setFirstResult(page[0]*page[1]).setMaxResults(page[1]).getResultList().stream().map(r->{var all=ConfigurationMapper.round(r,false);var m=new LinkedHashMap<String,Object>();for(String key:List.of("id","code","semesterId","name","status","opensAt","submissionDeadline","reviewDeadline"))m.put(key,all.get(key));return m;}).toList();
  long total=em.createQuery("select count(r) from MghpDotXet r"+where,Long.class).setParameter("semester",semester).getSingleResult();return Map.of("items",items,"page",page[0],"size",page[1],"totalElements",total);
 }
 void roundChildren(long id,JsonNode n,boolean replace){em.flush();if(replace)jdbc.update("DELETE dbo.mghp_chinh_sach_dot_xet WHERE dot_xet_id=?",id);for(var p:n.path("policyVersions")){var v=new LinkedHashMap<String,Object>();v.put("dot_xet_id",id);v.put("phien_ban_chinh_sach_id",ConfigRules.id(p.path("policyVersionId").asText()));v.put("tep_mau_don_id",p.path("applicationTemplateFileId").isNull()?null:ConfigRules.id(p.path("applicationTemplateFileId").asText()));v.put("thu_tu_hien_thi",p.path("order").isNull()?null:p.path("order").intValue());insert("mghp_chinh_sach_dot_xet",v);}em.flush();em.clear();}

 Map<String,Object> semester(long id){return one("SELECT id,ngay_bat_dau startDate,ngay_ket_thuc endDate,trang_thai_xac_minh_moc state,can_cu_xac_minh_moc evidence FROM dbo.hoc_ky WITH(UPDLOCK,HOLDLOCK) WHERE id=?",id);}
 Map<String,Object> file(long id){return one("SELECT trang_thai_luu_tru state,nguoi_so_huu_id ownerId,nguoi_tai_len_id uploaderId,kieu_noi_dung mime,thoi_diem_xoa deleted FROM dbo.tep_dinh_kem WITH(UPDLOCK,HOLDLOCK) WHERE id=?",id);}
 boolean boundTemplate(long id){return jdbc.queryForObject("SELECT COUNT(*) FROM dbo.mghp_chinh_sach_dot_xet b JOIN dbo.mghp_dot_xet d ON d.id=b.dot_xet_id WHERE b.tep_mau_don_id=?",Integer.class,id)>0;}
 boolean roundCodeTaken(String code,Long except){return jdbc.queryForObject("SELECT COUNT(*) FROM dbo.mghp_dot_xet WITH(UPDLOCK,HOLDLOCK) WHERE ma_dot_xet=? AND (? IS NULL OR id<>?)",Integer.class,code,except,except)>0;}
 boolean hasApplications(long id){return jdbc.queryForObject("SELECT COUNT(*) FROM dbo.mghp_ho_so WHERE dot_xet_id=?",Integer.class,id)>0;}
 boolean pending(long id){int rounds=jdbc.queryForObject("SELECT COUNT(*) FROM dbo.mghp_yeu_cau_bo_sung y WITH(UPDLOCK,HOLDLOCK) JOIN dbo.mghp_ho_so h ON h.id=y.ho_so_id WHERE (y.dot_tiep_nhan_id=? OR (y.dot_tiep_nhan_id IS NULL AND h.dot_xet_id=?)) AND (y.trang_thai IS NULL OR y.trang_thai NOT IN(N'completed',N'cancelled') OR y.trang_thai=N'completed' AND EXISTS(SELECT 1 FROM dbo.mghp_noi_dung_bo_sung n WHERE n.yeu_cau_bo_sung_id=y.id AND (n.ket_qua_xu_ly IS NULL OR n.ket_qua_xu_ly NOT IN(N'satisfied',N'unsatisfied',N'not_applicable'))))",Integer.class,id,id);
  int tasks=jdbc.queryForObject("SELECT COUNT(*) FROM dbo.cong_viec t WITH(UPDLOCK,HOLDLOCK) WHERE ma_phan_he=N'MGHP' AND (loai_doi_tuong=N'mghp_dot_xet' AND doi_tuong_id=? OR loai_doi_tuong=N'mghp_ho_so' AND EXISTS(SELECT 1 FROM dbo.mghp_ho_so h WHERE h.dot_xet_id=? AND CONVERT(varchar(20),h.id)=t.doi_tuong_id)) AND (trang_thai IS NULL OR trang_thai NOT IN(N'completed',N'cancelled'))",Integer.class,Long.toString(id),id);return rounds+tasks>0;
 }
 void publish(long notification,long id,OffsetDateTime now){jdbc.update("UPDATE dbo.mghp_dot_xet SET thong_bao_dot_xet_id=? WHERE id=?",notification,id);
   jdbc.update("INSERT dbo.nguoi_nhan_thong_bao(thong_bao_id,nguoi_dung_id,thoi_diem_tao) SELECT ?,u.id,? FROM dbo.nguoi_dung u WHERE u.dang_hoat_dong=1 AND u.thoi_diem_xoa IS NULL AND EXISTS(SELECT 1 FROM dbo.sinh_vien s WHERE s.nguoi_dung_id=u.id)",notification,now);
 em.clear();}
 String lastConfirmation(long id){var rows=jdbc.queryForList("SELECT TOP(1) ly_do FROM dbo.nhat_ky_thao_tac WHERE hanh_dong=N'POLICY_CONFIRM' AND loai_doi_tuong=N'mghp_phien_ban_chinh_sach' AND doi_tuong_id=? ORDER BY id DESC",Long.toString(id));return rows.isEmpty()?null:(String)rows.getFirst().get("ly_do");}
}
